import React, { useRef, useState } from 'react';
import api from '../services/api';
import CameraCaptureModal from './CameraCaptureModal';

// Botón para poner la foto de un producto/categoría. Ofrece DOS acciones bien
// diferenciadas en vez de dejar que el navegador decida:
// - "Tomar foto": abre una cámara en vivo (pide permiso, prueba la trasera primero).
// - "Subir archivo": abre el explorador de archivos/galería normal.
const ImageUploadButton = ({ value, onChange, label = 'Imagen' }) => {
  const fileInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');
  const [showCamera, setShowCamera] = useState(false);

  // Solo para mostrar: el nombre del archivo, no la URL completa (http://...)
  const displayName = value ? decodeURIComponent(value.split('/').pop()) : '';

  const uploadFile = async (file) => {
    setUploading(true);
    setError('');
    try {
      const formData = new FormData();
      formData.append('image', file);
      const res = await api.post('/uploads/image', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      onChange(res.data.data.url);
    } catch (err) {
      setError(err.response?.data?.message || 'Error al subir la imagen');
    } finally {
      setUploading(false);
    }
  };

  const handleFileInput = (e) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (file) uploadFile(file);
  };

  const handleCameraCapture = (file) => {
    setShowCamera(false);
    uploadFile(file);
  };

  return (
    <div>
      <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>{label}</label>
      <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
        <div style={{
          width: 64, height: 64, borderRadius: 10, flexShrink: 0,
          background: value ? `url(${value}) center/cover` : '#334155',
          display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 24,
          border: '1px solid #475569',
        }}>
          {!value && '🖼️'}
        </div>
        <div style={{ flex: 1 }}>
          <input
            type="text"
            className="input"
            placeholder="Sin imagen todavía"
            value={displayName}
            readOnly
            style={{ marginBottom: 6, cursor: 'default', color: value ? '#e2e8f0' : '#64748b' }}
          />
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <button
              type="button"
              onClick={() => setShowCamera(true)}
              disabled={uploading}
              className="btn"
              style={{ background: '#334155', color: '#e2e8f0', padding: '6px 12px', fontSize: 12 }}
            >
              📷 Tomar foto
            </button>
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
              className="btn"
              style={{ background: '#334155', color: '#e2e8f0', padding: '6px 12px', fontSize: 12 }}
            >
              🖼️ Subir archivo
            </button>
            {value && (
              <button
                type="button"
                onClick={() => onChange('')}
                className="btn"
                style={{ background: 'rgba(239,68,68,0.1)', color: '#ef4444', padding: '6px 12px', fontSize: 12 }}
              >
                Quitar
              </button>
            )}
          </div>
          {uploading && <p style={{ color: '#94a3b8', fontSize: 11, marginTop: 4 }}>Subiendo...</p>}
          {/* Sin "capture": esto SIEMPRE abre el explorador de archivos/galería, nunca la cámara directamente */}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            onChange={handleFileInput}
            style={{ display: 'none' }}
          />
          {error && <p style={{ color: '#ef4444', fontSize: 11, marginTop: 4 }}>{error}</p>}
        </div>
      </div>

      {showCamera && (
        <CameraCaptureModal
          onCapture={handleCameraCapture}
          onClose={() => setShowCamera(false)}
        />
      )}
    </div>
  );
};

export default ImageUploadButton;
